parser.script:
// 韩小圈：详情取分集最多的线路（基准 hanxiaoquanPickPlaylist 口径）。
function hxqStrip(base) { return String(base || '').replace(/\/+$/, ''); }
function hxqClean(text) {
  return String(text == null ? '' : text).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;/g, "'").replace(/\u3000/g, ' ').replace(/\s+/g, ' ').trim();
}
function parseEpisodes(raw, context) {
  var html = String(raw || '');
  if (!html) return [];
  var out = [], seen = {};
  var push = function (title, href) {
    if (!href || seen[href]) return;
    seen[href] = 1;
    var url = href;
    if (url.indexOf('//') === 0) url = 'https:' + url;
    else if (url.indexOf('/') === 0) url = hxqStrip(context.baseUrl) + url;
    if (!/jennyhow\.com/i.test(url) || !/\/play\/\d+-\d+-\d+\.html/i.test(url)) return;
    var number = 0;
    var nm = /(\d+)/.exec(title);
    if (nm) { number = parseInt(nm[1], 10); }
    if (!number || number <= 0) { number = out.length + 1; }
    out.push({ id: String(number), title: hxqClean(title) || ('第 ' + number + ' 集'), number: number, url: url });
  };
  // 多线路：取分集最多的 playlist 容器。
  var lineIDs = [];
  var tabRe = /href="#playlist(\d+)"[^>]*>[\s\S]{0,120}?<i[^>]*><\/i>\s*([^<]+)/gi;
  var tab;
  while ((tab = tabRe.exec(html))) {
    if (lineIDs.indexOf(tab[1]) < 0) lineIDs.push(tab[1]);
  }
  lineIDs.sort();
  if (lineIDs.length === 0) { lineIDs = ['']; }
  var best = null;
  for (var i = 0; i < lineIDs.length; i++) {
    var segment = html;
    if (lineIDs[i] !== '') {
      var marker = 'id="playlist' + lineIDs[i] + '"';
      var start = html.indexOf(marker);
      if (start < 0) continue;
      segment = html.slice(start + marker.length);
      var end = segment.indexOf('id="playlist');
      if (end >= 0) segment = segment.slice(0, end);
      else {
        var footer = segment.indexOf('class="module-footer"');
        if (footer >= 0) segment = segment.slice(0, footer);
      }
    }
    var eps = [];
    var epSeen = {};
    var epRe = /<a title="([^"]*)" href="(\/play\/\d+-\d+-\d+\.html)"/gi;
    var ep;
    while ((ep = epRe.exec(segment))) {
      if (epSeen[ep[2]]) continue;
      epSeen[ep[2]] = 1;
      eps.push([ep[1], ep[2]]);
    }
    if (!best || eps.length > best.length) { best = eps; }
  }
  if (best) {
    for (var k = 0; k < best.length; k++) { push(best[k][0], best[k][1]); }
  }
  return out;
}
var HXQ_NOW = /var\s+now\s*=\s*["']([^"']+)["']/i;
function parseVideo(raw, context) {
  var html = String(raw || '');
  var m = HXQ_NOW.exec(html);
  var url = m ? m[1] : '';
  if (!url) {
    var any = /https?:\/\/[^"'\s<>\\]+\.(?:m3u8|mp4)(?:\?[^"'\s<>\\]*)?/i.exec(html);
    url = any ? any[0] : '';
  }
  if (url && url.indexOf('//') === 0) url = 'https:' + url;
  return url;
}
// 搜索端点受「JS 自动挑战」保护：拦截页 200 返回极小体积，内联脚本写挑战
// cookie 后带 pass 参数自跳转（无人工要素）。首跳直接拿到真实结果页则原地
// 解析；否则从拦截页提取新鲜挑战令牌，__meta 二跳以 Cookie 头携带令牌重取
// 真实结果——令牌每次现取，站点轮换自愈。二跳 Cookie 头需引擎「显式头与
// 会话 jar 按名合并」语义支持（同名显式优先）。
function hxqAbsUrl(context, href) {
  var u = String(href || '');
  if (!u) return '';
  if (u.indexOf('//') === 0) return 'https:' + u;
  if (/^https?:\/\//i.test(u)) return u;
  return hxqStrip(context.baseUrl) + (u.charAt(0) === '/' ? u : '/' + u);
}
function hxqSearchList(html, context) {
  var page = String(html || '');
  if (!page || page.indexOf('module-item') < 0) return [];
  var out = [];
  var seen = {};
  var re = /<div class="module-item">([\s\S]*?)(?=<div class="module-item">|<div class="module-footer")/g;
  var m;
  while ((m = re.exec(page))) {
    var block = m[1];
    var href = '', title = '';
    var tagM = /<a\b[^>]*class="module-item-pic"[^>]*>/.exec(block);
    if (tagM) {
      var h = /href="([^"]+)"/.exec(tagM[0]);
      var t = /title="([^"]*)"/.exec(tagM[0]);
      if (h) href = h[1];
      if (t) title = hxqClean(t[1]);
    }
    if (!href) {
      var anyA = /<a\b[^>]*href="([^"]+)"/.exec(block);
      if (anyA) href = anyA[1];
    }
    if (!href || seen[href]) continue;
    seen[href] = 1;
    if (!title) {
      var t2 = /class="module-item-title"[^>]*>([^<]*)</.exec(block);
      if (t2) title = hxqClean(t2[1]);
    }
    if (!title) continue;
    var cover = '';
    var c1 = /data-src="([^"]+)"/.exec(block);
    if (c1) cover = c1[1];
    if (!cover) {
      var c2 = /<img\b[^>]*\ssrc="([^"]+)"/.exec(block);
      if (c2 && c2[1].indexOf('loading.') < 0) cover = c2[1];
    }
    var st = /class="module-item-text"[^>]*>([^<]*)</.exec(block);
    var idm = /\/(\d+)\.html/i.exec(href);
    out.push({
      id: idm ? idm[1] : String(out.length + 1),
      title: title,
      cover: cover,
      detailUrl: hxqAbsUrl(context, href),
      status: st ? hxqClean(st[1]) : ''
    });
  }
  return out;
}
function parseSearch(raw, context) {
  var page = String(raw || '');
  var list = hxqSearchList(page, context);
  if (list.length > 0) return list;
  var m = /idc_search_browser=([0-9a-fA-F]{8,})/.exec(page);
  if (!m) return list;
  var kw = encodeURIComponent(String(context.keyword || ''));
  return {
    __meta: true,
    __fetchUrl: hxqAbsUrl(context, '/search.php?searchword=' + kw + '&_idc_pass=1'),
    __fetchHeaders: { 'Cookie': 'idc_search_browser=' + m[1] },
    __fetchResponseType: 'text',
    __processor: 'hxqSearchList'
  };
}
